  $factory=new DigiForge\ProductFactory\Repository();$opp=$factory->create('opportunity',['title'=>'Local draft review fixture']);$case->assertNotWPError($opp);$family=$factory->create('product_family',['opportunity_id'=>$opp['id'],'name'=>'Draft fixture']);$case->assertNotWPError($family);$product=$factory->create('product',['product_family_id'=>$family['id'],'name'=>'Draft fixture']);$case->assertNotWPError($product);$version=$factory->create('product_version',['product_id'=>$product['id'],'version_label'=>'v1']);$case->assertNotWPError($version);foreach(['REVIEW','APPROVED']as $state)$case->assertNotWPError($factory->transition('product_version',(int)$version['id'],$state));
